{"cmd":"cat <<'JS' > /root/output/js/visualization.js
const width = 720;
const height = 560;

const svg = d3
  .select("#bubble-chart")
  .append("svg")
  .attr("width", width)
  .attr("height", height)
  .attr("viewBox", `0 0 ${width} ${height}`)
  .attr("role", "img")
  .attr("aria-label", "Bubble chart of stocks grouped by sector and sized by market capitalization");

const tooltip = d3.select("#tooltip");

function formatNumber(value) {
  const formatter = d3.format(".2f");
  const trimmed = formatter(value).replace(/\.0+$|(?<=\.[0-9]*)0+$/, "");
  return trimmed;
}

function formatMarketCap(value) {
  if (value === null || Number.isNaN(value)) {
    return "N/A";
  }
  const abs = Math.abs(value);
  if (abs >= 1e12) {
    return `${formatNumber(value / 1e12)}T`;
  }
  if (abs >= 1e9) {
    return `${formatNumber(value / 1e9)}B`;
  }
  if (abs >= 1e6) {
    return `${formatNumber(value / 1e6)}M`;
  }
  return formatNumber(value);
}

d3.csv("data/stock-descriptions.csv", (d) => ({
  ticker: d.ticker,
  sector: d.sector,
  fullName: d["full name"],
  marketCap: d.marketCap ? +d.marketCap : null,
}))
  .then((raw) => {
    const data = raw
      .filter((d) => d.ticker && d.sector)
      .sort((a, b) => d3.ascending(a.ticker, b.ticker));

    const sectors = Array.from(new Set(data.map((d) => d.sector))).sort();
    const center = { x: width / 2, y: height / 2 };
    const offsets = [
      [-170, -120],
      [0, -120],
      [170, -120],
      [-85, 120],
      [85, 120],
    ];

    const clusterCenters = new Map();
    sectors.forEach((sector, i) => {
      const offset = offsets[i % offsets.length];
      clusterCenters.set(sector, {
        x: center.x + offset[0],
        y: center.y + offset[1],
      });
    });

    const capValues = data
      .map((d) => d.marketCap)
      .filter((d) => d !== null && !Number.isNaN(d));

    const radiusScale = d3
      .scaleSqrt()
      .domain(d3.extent(capValues))
      .range([12, 40]);

    const etfRadius = 16;

    data.forEach((d) => {
      d.radius = d.marketCap ? radiusScale(d.marketCap) : etfRadius;
    });

    const sectorCounts = new Map();
    data.forEach((d) => {
      const idx = sectorCounts.get(d.sector) || 0;
      sectorCounts.set(d.sector, idx + 1);
      const col = idx % 5;
      const row = Math.floor(idx / 5);
      const base = clusterCenters.get(d.sector);
      d.x = base.x + (col - 2) * 14;
      d.y = base.y + (row - 0.5) * 14;
    });

    const color = d3
      .scaleOrdinal()
      .domain(sectors)
      .range(d3.schemeTableau10.slice(0, sectors.length));

    const simulation = d3
      .forceSimulation(data)
      .force(
        "x",
        d3.forceX((d) => clusterCenters.get(d.sector).x).strength(0.6)
      )
      .force(
        "y",
        d3.forceY((d) => clusterCenters.get(d.sector).y).strength(0.6)
      )
      .force("collide", d3.forceCollide((d) => d.radius + 1))
      .stop();

    for (let i = 0; i < 240; i += 1) {
      simulation.tick();
    }

    const legend = svg
      .append("g")
      .attr("class", "legend")
      .attr("transform", "translate(20, 20)");

    const legendItem = legend
      .selectAll("g")
      .data(sectors)
      .join("g")
      .attr("transform", (d, i) => `translate(0, ${i * 18})`);

    legendItem
      .append("rect")
      .attr("width", 12)
      .attr("height", 12)
      .attr("fill", (d) => color(d))
      .attr("rx", 2);

    legendItem
      .append("text")
      .attr("x", 18)
      .attr("y", 10)
      .text((d) => d);

    const nodes = svg.append("g").attr("class", "nodes");

    const node = nodes
      .selectAll("g")
      .data(data, (d) => d.ticker)
      .join("g")
      .attr("class", "node")
      .attr("transform", (d) => `translate(${d.x}, ${d.y})`);

    node
      .append("circle")
      .attr("r", (d) => d.radius)
      .attr("fill", (d) => color(d.sector));

    node
      .append("text")
      .attr("text-anchor", "middle")
      .attr("dy", "0.35em")
      .text((d) => d.ticker);

    function showTooltip(event, d) {
      if (!d.marketCap) {
        return;
      }
      tooltip
        .classed("visible", true)
        .html(
          `<strong>${d.ticker}</strong><br/>${d.fullName}<br/>${d.sector}`
        )
        .style("left", `${event.pageX + 12}px`)
        .style("top", `${event.pageY - 18}px`);
    }

    function hideTooltip() {
      tooltip.classed("visible", false);
    }

    function setSelected(ticker) {
      d3.selectAll(".node").classed("selected", (d) => d.ticker === ticker);
      d3
        .selectAll(".data-row")
        .classed("selected", (d) => d.ticker === ticker);
    }

    node
      .on("mouseenter", showTooltip)
      .on("mousemove", showTooltip)
      .on("mouseleave", hideTooltip)
      .on("click", (event, d) => {
        setSelected(d.ticker);
      });

    const table = d3.select("#stock-table");
    const columns = [
      "Ticker symbol",
      "Full company name",
      "Sector",
      "Market cap",
    ];

    table.append("thead").append("tr").selectAll("th")
      .data(columns)
      .join("th")
      .text((d) => d);

    const tbody = table.append("tbody");

    const rows = tbody
      .selectAll("tr")
      .data(data, (d) => d.ticker)
      .join("tr")
      .attr("class", "data-row")
      .on("click", (event, d) => {
        setSelected(d.ticker);
      });

    rows
      .selectAll("td")
      .data((d) => [
        d.ticker,
        d.fullName,
        d.sector,
        formatMarketCap(d.marketCap),
      ])
      .join("td")
      .text((d) => d);
  })
  .catch((error) => {
    svg
      .append("text")
      .attr("x", 20)
      .attr("y", 30)
      .attr("fill", "#b91c1c")
      .text("Failed to load data. Check the data path and server.");
    console.error(error);
  });
JS"}

